function onSlot(slot) {
  block = propose(parent=head);
  collectLatestAttestations(block);
  head = lmdGhost(justifiedCheckpoint);
  if votes(target) >= 2/3: justify(target);
  if consecutiveJustified(): finalize(source);
}

function runRound(round) {
  proposal = proposer(round).broadcast();
  prevotes = collectPrevotes(proposal);
  if power(prevotes) >= 2/3: lock(proposal.value);
  precommits = collectPrecommits(lockedValue);
  if power(precommits) >= 2/3: commit(lockedValue);
}

function mintWithProof(proof) {
  require(lightClient.synced());
  require(verifyInclusion(proof));
  require(!proof.used);
  mint(proof.amount);
}

function waitFinality(event) {
  confirmations = head - event.height;
  require(confirmations >= required);
  require(!reorged(event.blockHash));
  release(event.message);
}

function receiveMessage(message, proof) {
  require(verifySourceEvent(proof));
  require(!executed[message.id]);
  executePayload(message.payload);
  executed[message.id] = true;
}

function authorize(message, sigs) {
  valid = filterActiveSigners(sigs);
  require(valid.length >= threshold);
  aggregate(valid);
  execute(message);
}

function submitOptimisticBatch(batch) {
  postStateRoot(batch.claimedRoot);
  if challenger.detectsMismatch(): openChallenge();
  segment = bisectExecutionTrace(batch);
  fraud = verifyOneStep(segment);
  if fraud: revertBatchAndSlash();
}

function executeCrossMessage(message) {
  digest = hash(domain, message.nonce, payload);
  require(!executed[domain][nonce]);
  executed[domain][nonce] = true;
  execute(payload);
}

function submitValidityBatch(batch) {
  trace = execute(batch.transactions);
  publicInputs = [oldRoot, newRoot];
  proof = prover.generate(trace, publicInputs);
  require(verifier.verify(proof, publicInputs));
  rollupStateRoot = newRoot;
}

function verifySignedMessage(message, nonce, signature) {
  digest = H(message, nonce);
  signer = recover(digest, signature);
  require(signer == trustedPublicKey);
  require(!usedNonce[nonce]);
  usedNonce[nonce] = true;
}

function verifyHashChain(records) {
  bytes = canonicalSerialize(record.payload);
  hash = H(bytes, record.parentHash);
  require(hash == record.hash);
  require(record.parentHash == previous.hash);
  repairFrom(firstInvalidIndex);
}

function verifyMerkle(leaf, siblings, expectedRoot) {
  hash = H(leaf);
  for sibling in siblings:
    hash = H(ordered(hash, sibling));
  require(hash == expectedRoot);
  return true;
}

function thresholdSign(message) {
  shares = splitSecret(privateKey, n, t);
  partials = signWithShares(message, shares);
  require(validPartials(partials) >= t);
  signature = aggregate(partials);
  require(verify(groupPublicKey, message, signature));
}

function verifyZk(commitment, challenge, response) {
  require(commitment.isBound());
  expected = relation(response, challenge);
  require(expected == commitment);
  repeatUntil(soundnessErrorLow());
}

function validateChain(blocks) {
  require(blocks[0].parentHash == "genesis");
  for i in 1..blocks.length:
    require(blocks[i].parentHash == blocks[i-1].hash);
  markForksByHeight();
  chooseCanonicalBranch();
}

function buildMerkleTree(items) {
  leaves = sort(items).map(hash);
  while leaves.length > 1:
    leaves = pairwiseHash(leaves);
  return leaves[0];
  updatePath(changedLeaf);
}

function updateTrie(key, value) {
  path = encodeNibbles(key);
  node = walkCompressedPath(path);
  leaf.value = value;
  root = rehashToRoot(leaf);
  proveAbsence(missingKey);
}

function snapshot(state) {
  root = hashSortedAccounts(state);
  deltas = recordDirtyWrites();
  if executionFails: rollback(deltas);
  require(hashSortedAccounts(state) == root);
}

function validateUtxoTx(tx) {
  require(allInputsUnspent(tx.inputs));
  require(sum(inputs) >= sum(outputs) + fee);
  markSpent(tx.inputs);
  addOutputs(tx.outputs);
}

function hotstuff(view) {
  highQC = collectNewView();
  proposal = leader.propose(extend(highQC.block));
  votes = replicas.voteIfSafe(proposal, lockedBlock, highQC);
  qc = aggregate(votes, quorum(n, f));
  lock(qc.block);
  if (threeChain(qc.block.parent.parent, qc.block.parent, qc.block)) commit(grandparent(qc.block));
  onLeaderDelay() moveToNextView(highQC);
}

function dhtLookup(key) {
  shortlist = nearestFromBuckets(key);
  shortlist = sortByXorDistance(shortlist, key);
  while hasUnqueriedCloser(shortlist):
    replies = query(alphaClosestUnqueried);
    shortlist = mergeAndSortByXor(replies);
  return closestValue();
}

function gossip(message) {
  frontier = seedPeers(message);
  targets = chooseFanout(frontier, fanout);
  deliverToUnseen(targets);
  ignoreDuplicate(message.id);
  require(coverage() >= target);
}

function reliableSend(packets) {
  sendUpTo(congestionWindow);
  waitForAckOrDeadline();
  if deadlineExceeded: markLost(packet);
  retransmit(lostPackets);
  congestionWindow = backoffOrGrow();
  require(allDelivered());
}

function discoverPeers(localNetwork, minVersion) {
  seeds = connectBootnodes();
  addrs = requestAddr(seeds);
  candidates = scoreAndDeduplicate(addrs);
  for peer in candidates:
    require(handshake(peer.network, peer.version));
  probeHealthyPeers();
  banMaliciousPeers();
}

function handlePartition(topology) {
  cutSet = findCrossRegionLinks(topology);
  block(cutSet);
  syncWithinRegion();
  heal(cutSet);
  exchangeVersions();
  mergeByConsensusRule();
}

function proofOfStake(slot) {
  seed = mixRandomness(history, slot);
  proposer = weightedSelect(activeValidators, seed);
  committee = shuffle(activeValidators, seed, slot);
  block = proposer.propose(slot);
  attestations = committee.sign(source, target, block.root);
  aggregate = aggregateSignatures(attestations);
  require(stake(attestations) >= twoThirds(activeStake));
  justify(epoch);
  if (previousJustified(epoch - 1)) finalize(epoch - 1);
  slash(doubleVotesOrSurroundVotes(attestations));
}

function mine(parent, txs, difficulty) {
  block = assembleBlock(parent, txs);
  target = prefixZeros(difficulty);
  do {
    nonce++;
    hash = H(parent.hash, block.body, nonce);
  } while (!hash.startsWith(target));
  broadcast(block, nonce, hash);
  require(parentKnown(block) && validateWork(hash, target));
  if (work(block.chain) > work(local.chain)) switchTip(block);
  difficulty = retarget(window, targetSpacing);
}

function raft(command) {
  candidate = onElectionDelay();
  votes = requestVote(candidate.term, candidate.lastLogIndex, candidate.lastLogTerm);
  require(votes.majority() && candidate.logAtLeastAsNew());
  leader.append(command);
  appendEntries(prevLogIndex, prevLogTerm, entries);
  if (prevLogMatches() && acknowledgements.majority()) commitIndex++;
  heartbeat(commitIndex);
  repairLaggingFollowers(nextIndex--, appendEntries);
}

function validateBlock(block) {
  require(block.parent == localTip.hash);
  require(root(block.txs) == block.txRoot);
  require(root(receipts) == block.receiptRoot);
  require(execute(block).stateRoot == block.stateRoot);
  acceptOrReject(block);
}

function buildBlock(mempool, baseFee) {
  candidates = filter(tx.maxFeePerGas >= baseFee);
  selected = sortByEffectiveTip(candidates);
  gasUsed = execute(selected);
  burn(baseFee * gasUsed);
  nextBaseFee = adjust(baseFee, gasUsed, targetGas);
}

function callA() {
  frame.push(A);
  ok = B.call(data);
  require(ok);
  frame.pop();
  require(depth < MAX_DEPTH);
}

function executeWithGas(tx) {
  require(gasUsed <= gasLimit);
  gasUsed += cost(op);
  if gasUsed > gasLimit: revert();
  refund = cappedRefund();
  settleFee(gasUsed - refund);
}

function acceptTx(tx) {
  expected = accountNonce(tx.sender);
  if tx.nonce > expected: queue(tx);
  if sameNonceExists(tx): require(priceBump(tx));
  gossipLocalPool(tx);
  includeContinuousNonce();
}

function includeAccountTxs(txs) {
  require(tx.nonce == account.nonce);
  execute(tx);
  account.nonce += 1;
  replaceByHigherFee(sameNonceTx);
}

function submitTransaction(tx) {
  txHash = sign(tx);
  validateForMempool(tx);
  includeInBlock(tx);
  receipt = execute(tx);
}

function setConfig(value) {
  require(hasRole(ADMIN, msg.sender));
  config = value;
  emit Audit(msg.sender, "setConfig");
}

function executeFlashLoan() {
  loan = borrow(pool);
  manipulateMarket(loan);
  exploitProtocol();
  repay(loan + fee);
  require(blockImpact < limit);
}

function mint(amount, price) {
  require(amount <= MAX_AMOUNT);
  total = checkedMul(amount, price);
  require(total <= cap);
  mint(total);
}

function priceGuard() {
  spot = amm.getSpotPrice();
  require(abs(spot - twap) < maxDeviation);
  price = median(oracles);
  borrowAgainst(price);
}

function withdraw() {
  require(balance[msg.sender] > 0);
  amount = balance[msg.sender];
  sendValue(msg.sender, amount);
  balance[msg.sender] = 0;
  nonReentrant();
}
